mapper.select:
SELECT * FROM ( SELECT TB.* FROM ( SELECT ROW_NUMBER() OVER (ORDER BY A.MHS_MREGDATE DESC) AS RNUM, B.GROUP_NM AS "mhsBrandnm", C.CENTER_NM AS "mhsCenternm", A.MHS_MONITORNM AS "mhsMonitornm", A.MHS_MONITORCD AS "mhsMonitorcd", A.MHS_IPADDR AS "mhsIpaddr", A.MHS_MACADDR AS "mhsMacaddr", CASE
WHEN A.MHS_LASTCONN > (NOW() - INTERVAL '10 minute') AND A.MHS_LASTCONN IS NOT NULL
THEN 'ON' ELSE 'OFF' END AS mhsLastconn, A.MHS_REMARK AS "mhsRemark" FROM TB_MHSMONITORINFO A JOIN LETTNAUTHORGROUPINFO B ON A.MHS_BRANDCD = B.GROUP_ID JOIN TB_CENTERINFO C ON A.MHS_CENTERCD = C.CENTER_ID JOIN LETTNAUTHORGROUPINFO D ON C.ROLE_CODE = D.GROUP_ID WHERE A.MHS_MONITORSTATUS != 'N'
AND A.MHS_BRANDCD IN ( WITH RECURSIVE cte AS ( SELECT GROUP_ID, PARENT_GROUP_ID FROM LETTNAUTHORGROUPINFO WHERE GROUP_ID = #{groupId} UNION ALL SELECT g.GROUP_ID, g.PARENT_GROUP_ID FROM LETTNAUTHORGROUPINFO g JOIN cte ON g.PARENT_GROUP_ID = cte.GROUP_ID ) SELECT GROUP_ID FROM cte )
AND A.MHS_BRANDCD = #{mhsBrandcd}
AND A.MHS_CENTERCD = #{mhsCentercd}
AND A.MHS_MONITORNM LIKE CONCAT('%', #{searchKeyword}, '%')
AND A.MHS_MONITORCD LIKE CONCAT('%', #{searchKeyword}, '%')
AND A.MHS_IPADDR LIKE CONCAT('%', #{searchKeyword}, '%')
AND A.MHS_MACADDR LIKE CONCAT('%', #{searchKeyword}, '%')
) TB ) TA WHERE TA.RNUM BETWEEN #{firstIndex} + 1 AND #{firstIndex} + #{recordCountPerPage}

mapper.update:
UPDATE TB_MHSMONITORINFO SET MHS_MONITORNM = #{mhsMonitornm}, MHS_BRANDCD = #{mhsBrandcd}, MHS_CENTERCD = #{mhsCentercd,jdbcType=VARCHAR}, MHS_MVIEWTYPE = #{mhsMviewtype,jdbcType=VARCHAR}, MHS_MUPDATEID = #{mhsMupdateid,jdbcType=VARCHAR}, MHS_MUPDATEDATE = NOW(),
MHS_REMARK = #{mhsRemark},
MHS_MONITORSTATUS = #{mhsMonitorstatus,jdbcType=VARCHAR} WHERE MHS_MONITORCD = #{mhsMonitorcd}

UPDATE TB_MHSMONITORINFO SET
                             MHS_IPADDR = #{mhsIpaddr},
                             MHS_MACADDR = #{mhsMacaddr},
                             MHS_MVIEWTYPE = #{mhsMviewtype,jdbcType=VARCHAR}
WHERE MHS_MONITORCD = #{mhsMonitorcd}
